Tool response:
Tool: create_or_update_home_check
Description: Create Or Update Home Check
Parameters:
    {
      "type": "object",
      "properties": {
        "adoption_application_id": {
          "type": "integer",
          "title": "Adoption Application Id"
        },
        "completed_date": {
          "type": "string",
          "format": "date",
          "title": "Completed Date"
        },
        "notes": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Notes"
        }
      },
      "required": [
        "adoption_application_id",
        "completed_date"
      ]
    }

Tool response:
Tool: record_payment
Description: Record Payment
Parameters:
    {
      "type": "object",
      "properties": {
        "adoption_application_id": {
          "type": "integer",
          "title": "Adoption Application Id"
        },
        "amount": {
          "type": "number",
          "title": "Amount"
        },
        "payment_method": {
          "type": "string",
          "enum": [
            "Credit Card",
            "Debit Card",
            "Cash",
            "Bank Transfer"
          ],
          "title": "Payment Method"
        },
        "payment_date": {
          "type": "string",
          "format": "date",
          "title": "Payment Date"
        },
        "status": {
          "anyOf": [
            {
              "type": "string",
              "enum": [
                "Pending",
                "Paid"
              ]
            },
            {
              "type": "null"
            }
          ],
          "title": "Status",
          "default": "Paid"
        }
      },
      "required": [
        "adoption_application_id",
        "amount",
        "payment_method",
        "payment_date"
      ]
    }
